std::string htmlify(const std::string& markdown) {
    std::istringstream iss(markdown);
    std::string line;
    std::string tag;

    // Process each line
    while (iss >> line) {
        if (line.size() > 1 && line[1] == '#') {
            tag = "h1";
            iss.ignore(std::numeric_limits<iosstream>::max(), '\n');
        } else if (line.size() > 1 && line[1] == '//') {
            tag = "h2";
            iss.ignore(std::numeric_limits<iosstream>::max(), '\n');
        } else if (line.size() > 1 && line[1] == 'p') {
            tag = "p";
            iss.ignore(std::numeric_limits<iosstream>::max(), '\n');
        } else {
            tag = line;
        }

        // HTML tag creation
        switch(tag) {
            case "h1":
                return "<h1>" + std::to_string(line) + "</h1>";
            case "h2":
                return "<h2>" + std::to_string(line) + "</h2>";
            case "p":
                return "<p>" + line + "</p>";
            default:
                throw std::invalid_argument("Unknown markdown tag.");
        }
    }

    // Handle empty strings
    if (!iss.eof()) {
        return tag + std::string("") + "." + line;
    }

    return tag;
}

